  if (spec.additionalProperties !== undefined) schema.additionalProperties = spec.additionalProperties
  if (spec.items !== undefined) schema.items = toJsonSchema(Array.isArray(spec.items) ? spec.items[0] : spec.items)
  if (spec.properties !== undefined && spec.properties !== null) {
    const compiled = compileProperties(spec.properties)
    schema.properties = compiled.properties
    if (compiled.required.length > 0) schema.required = compiled.required
  }
  return schema
