    name: TOOL_NAME,
    description: TOOL_DESCRIPTION,
    parameters: plainClone(TOOL_PARAMETERS_JSON_SCHEMA),
    timeoutMs: TOOL_TIMEOUT_MS,
    output: { schema: plainClone(OUTPUT_JSON_SCHEMA), render: behaviour.render },
    execute: behaviour.execute,
